import JSON

"""
	gen( x, a, b, name )

Generate fixture data and write to file.

The logarithm of the CDF is evaluated in extended precision from the textbook formula `ln(1 - (1 - x^a)^b)`, as forming `1 - x^a` in double precision rounds away the low-order bits of `x^a` (all of them for `x^a < 2^-53`).

# Arguments

* `x`: input value
* `a`: first shape parameter
* `b`: second shape parameter
* `name::AbstractString`: output filename
"""
function gen( x, a, b, name )
	z = setprecision( BigFloat, 2048 ) do
		Float64.( log.( 1 .- ( 1 .- BigFloat.( x ) .^ BigFloat.( a ) ) .^ BigFloat.( b ) ) )
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("a", a),
		("b", b),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Random values:
x = rand( 1000 );
a = ( rand( 1000 ) .* 5.0 ) .+ 0.5;
b = ( rand( 1000 ) .* 5.0 ) .+ 0.5;
gen( x, a, b, "data.json" );

# Small `x` (with `a` small enough that `x^a` does not underflow):
x = exp10.( range( -100.0, stop = -1.0, length = 1000 ) );
a = ( rand( 1000 ) .* 2.5 ) .+ 0.5;
b = ( rand( 1000 ) .* 5.0 ) .+ 0.5;
gen( x, a, b, "small_x.json" );

# `x` close to `1`:
x = 1.0 .- exp10.( range( -15.0, stop = -1.0, length = 1000 ) );
a = ( rand( 1000 ) .* 5.0 ) .+ 0.5;
b = ( rand( 1000 ) .* 5.0 ) .+ 0.5;
gen( x, a, b, "large_x.json" );
